<script>
(() => {
  const hero = document.getElementById('coin-hero');
  const hctx = hero.getContext('2d', { alpha: false });
  let running = true, frame = 0, start = performance.now();

  const palettes = {
    hero:   {base:'#a66d32', light:'#e7bd70', dark:'#392113', rim:'#e2b25e', ink:'#24170d'},
    bronze: {base:'#8d4c29', light:'#d78b4c', dark:'#27150e', rim:'#d59a5d', ink:'#23140d'},
    silver: {base:'#82929a', light:'#e5eff0', dark:'#293238', rim:'#d8e4e2', ink:'#20292c'},
    gold:   {base:'#b77a20', light:'#ffe39a', dark:'#40250a', rim:'#f4c75c', ink:'#352009'},
    black:  {base:'#222d31', light:'#839d9b', dark:'#050708', rim:'#607878', ink:'#050707'}
  };

  function rgba(hex, a) {
    const n = parseInt(hex.slice(1),16);
    return `rgba(${(n>>16)&255},${(n>>8)&255},${n&255},${a})`;
  }
  function ellipsePath(ctx, cx, cy, R, sy, rot) {
    ctx.save();
    ctx.translate(cx, cy);
    ctx.rotate(rot);
    ctx.scale(1, sy / R);
    ctx.beginPath();
    ctx.arc(0, 0, R, 0, Math.PI * 2);
    ctx.restore();
  }
  function localPoint(cx,cy,rot,x,y,sy,R) {
    const c=Math.cos(rot),s=Math.sin(rot);
    return {x:cx + x*c - y*(sy/R)*s, y:cy + x*s + y*(sy/R)*c};
  }
  function ringText(ctx, text, radius, top) {
    const chars = text.split('');
    const spread = Math.min(2.18, chars.length * .17);
    ctx.save();
    ctx.font = '800 11px system-ui, sans-serif';
    ctx.textAlign='center'; ctx.textBaseline='middle';
    chars.forEach((ch,i) => {
      const a = (top ? -Math.PI/2 - spread/2 : Math.PI/2 - spread/2) + spread*(i/(chars.length-1 || 1));
      const x=Math.cos(a)*radius, y=Math.sin(a)*radius;
      ctx.save(); ctx.translate(x,y); ctx.rotate(a+(top ? Math.PI/2 : -Math.PI/2)); ctx.fillText(ch,0,0);ctx.restore();
    });
    ctx.restore();
  }

  function renderCoin(ctx, W, H, t, palette, small=false) {
    const yaw = t * Math.PI * 2;
    const pitch = .72 * Math.sin(yaw);
    const nx = Math.sin(yaw) * Math.cos(pitch);
    const ny = -Math.sin(pitch);
    const nz = Math.cos(yaw) * Math.cos(pitch);
    const visibleFront = nz >= 0;
    const normalLength = Math.hypot(nx, ny);
    const normalAngle = Math.atan2(ny,nx);
    const majorRot = normalAngle + Math.PI/2;
    const R = small ? Math.min(W*.31,H*.39) : Math.min(W*.285,H*.37);
    const faceSy = Math.max(R * Math.abs(nz), R*.018);
    const edgeSy = faceSy + R * (.105 * normalLength + .018);
    const cx = W*.5, cy = H*.5;
    const faceName = visibleFront ? 'front' : 'back';

    ctx.clearRect(0,0,W,H);
    const bg=ctx.createRadialGradient(cx,cy,R*.1,cx,cy,Math.max(W,H)*.72);
    bg.addColorStop(0,'#18201f');
    bg.addColorStop(.42,'#0d1113');
    bg.addColorStop(1,'#080a0b');
    ctx.fillStyle=bg;ctx.fillRect(0,0,W,H);

    // Grounded but restrained shadow
    ctx.save();
    ctx.translate(cx,cy+R*.82);
    ctx.scale(1,.17);
    const shadow=ctx.createRadialGradient(0,0,0,0,0,R*1.13);
    shadow.addColorStop(0,'rgba(0,0,0,.58)');shadow.addColorStop(1,'rgba(0,0,0,0)');
    ctx.fillStyle=shadow;ctx.beginPath();ctx.arc(0,0,R*1.15,0,Math.PI*2);ctx.fill();
    ctx.restore();

    // Dark cylindrical edge shell
    ellipsePath(ctx,cx,cy,R,edgeSy,majorRot);
    const edgeGrad=ctx.createLinearGradient(cx-R,cy-R,cx+R,cy+R);
    edgeGrad.addColorStop(0,palette.dark);
    edgeGrad.addColorStop(.28,palette.rim);
    edgeGrad.addColorStop(.5,palette.dark);
    edgeGrad.addColorStop(.76,palette.light);
    edgeGrad.addColorStop(1,palette.dark);
    ctx.fillStyle=edgeGrad;ctx.fill();
    ctx.lineWidth=small?2:4;ctx.strokeStyle=rgba(palette.light,.75);ctx.stroke();

    // Reeded edge: many individually highlighted radial cuts
    const ridges=small?54:104;
    ctx.save();
    ctx.lineCap='butt';
    for(let i=0;i<ridges;i++){
      const a=(i/ridges)*Math.PI*2;
      const outer=localPoint(cx,cy,majorRot,Math.cos(a)*R,Math.sin(a)*R,edgeSy,R);
      const inner=localPoint(cx,cy,majorRot,Math.cos(a)*R*.91,Math.sin(a)*R,edgeSy,R);
      const glint = .25 + .55*Math.max(0,Math.cos(a - yaw*1.7));
      ctx.strokeStyle=i%2 ? rgba(palette.dark,.8) : rgba(palette.light,glint);
      ctx.lineWidth=small?1:1.65;
      ctx.beginPath();ctx.moveTo(inner.x,inner.y);ctx.lineTo(outer.x,outer.y);ctx.stroke();
    }
    ctx.restore();

    // Face, clipped to projected circular plane
    if (Math.abs(nz) > .025) {
      ctx.save();
      ellipsePath(ctx,cx,cy,R*.94,faceSy*.94,majorRot);
      ctx.clip();

      ctx.save();
      ctx.translate(cx,cy);ctx.rotate(majorRot);ctx.scale(1,faceSy/R);
      const surface=ctx.createRadialGradient(-R*.28,-R*.37,R*.08,0,0,R*1.05);
      surface.addColorStop(0,palette.light);
      surface.addColorStop(.22,palette.base);
      surface.addColorStop(.65,palette.base);
      surface.addColorStop(1,palette.dark);
      ctx.fillStyle=surface;ctx.beginPath();ctx.arc(0,0,R,0,Math.PI*2);ctx.fill();

      // A moving narrow specular light, rendered on the metal itself
      const hx=R*.72*Math.sin(yaw*1.21+.45);
      const hy=R*.55*Math.cos(yaw*1.63-.2);
      const spec=ctx.createRadialGradient(hx,hy,0,hx,hy,R*.43);
      spec.addColorStop(0,'rgba(255,255,244,.93)');
      spec.addColorStop(.09,rgba(palette.light,.72));
      spec.addColorStop(.34,rgba(palette.light,.13));
      spec.addColorStop(1,'rgba(255,255,255,0)');
      ctx.globalCompositeOperation='screen';ctx.fillStyle=spec;ctx.beginPath();ctx.arc(hx,hy,R*.5,0,Math.PI*2);ctx.fill();
      ctx.globalCompositeOperation='source-over';

      // Fine machine-turn texture
      ctx.strokeStyle=rgba(palette.light,.17);ctx.lineWidth=1;
      for(let r=R*.27;r<R*.88;r+=small?11:16){ctx.beginPath();ctx.arc(0,0,r,0,Math.PI*2);ctx.stroke()}
      ctx.restore();

      // Relief artwork in local coin coordinates
      ctx.save();
      ctx.translate(cx,cy);ctx.rotate(majorRot);ctx.scale(1,faceSy/R);
      const line=small?1.6:2.5;
      ctx.lineWidth=line;
      ctx.strokeStyle=rgba(palette.dark,.88);ctx.beginPath();ctx.arc(0,0,R*.79,0,Math.PI*2);ctx.stroke();
      ctx.lineWidth=line*.55;ctx.strokeStyle=rgba(palette.light,.82);ctx.beginPath();ctx.arc(0,0,R*.755,0,Math.PI*2);ctx.stroke();

      const emboss = (draw) => {
        ctx.save();ctx.translate(2.2,2.2);ctx.fillStyle=rgba(palette.dark,.72);ctx.strokeStyle=rgba(palette.dark,.72);draw();ctx.restore();
        ctx.save();ctx.translate(-1.35,-1.35);ctx.fillStyle=rgba('#ffffff',.46);ctx.strokeStyle=rgba(palette.light,.8);draw();ctx.restore();
        ctx.save();ctx.fillStyle=palette.ink;ctx.strokeStyle=palette.ink;draw();ctx.restore();
      };
      if(faceName==='front'){
        emboss(() => {
          ctx.beginPath();
          ctx.moveTo(-R*.43,-R*.26);ctx.lineTo(-R*.23,R*.31);ctx.lineTo(0,-R*.05);ctx.lineTo(R*.23,R*.31);ctx.lineTo(R*.43,-R*.26);
          ctx.lineTo(R*.28,-R*.31);ctx.lineTo(R*.05,.05*R);ctx.lineTo(-R*.18,-R*.31);ctx.closePath();ctx.fill();
        });
        ctx.fillStyle=palette.ink;ctx.font=`900 ${small?10:15}px system-ui,sans-serif`;ctx.textAlign='center';ctx.textBaseline='middle';
        ringText(ctx,'WASTEDTOKEN',R*.60,true);
        ringText(ctx,'MINT • EST. FOREVER',R*.60,false);
        ctx.fillText('⌁',0,R*.43);
      } else {
        emboss(() => {
          ctx.font=`900 ${small?23:42}px Georgia,serif`;ctx.textAlign='center';ctx.textBaseline='middle';ctx.fillText('10,000',0,-R*.08);
          ctx.font=`800 ${small?8:13}px system-ui,sans-serif`;ctx.fillText('TOKENS',0,R*.20);
        });
        ctx.fillStyle=palette.ink;ctx.font=`800 ${small?8:12}px system-ui,sans-serif`;ctx.textAlign='center';ctx.textBaseline='middle';
        ringText(ctx,'LEGAL TENDER NOWHERE',R*.60,true);
        ringText(ctx,'KEEP THE RECEIPT',R*.60,false);
        ctx.beginPath();ctx.arc(0,R*.43,R*.045,0,Math.PI*2);ctx.fill();
      }
      ctx.restore();
      ctx.restore();
    }

    // Bright lip gives the silhouette its minted, dimensional edge
    ellipsePath(ctx,cx,cy,R*.95,faceSy*.95,majorRot);
    ctx.strokeStyle=rgba(palette.light,.78);ctx.lineWidth=small?1:2.4;ctx.stroke();
  }

  function heroRender(t){ renderCoin(hctx,hero.width,hero.height,Math.max(0,Math.min(1,t)),palettes.hero,false); }

  function tick(now){
    if(!running)return;
    const t=((now-start)%9000)/9000;
    heroRender(t);
    frame=requestAnimationFrame(tick);
  }
  heroRender(0);
  frame=requestAnimationFrame(tick);

  window.demo = {
    canvas: hero,
    setTime(t) {
      heroRender(t);
    },
    pause() {
      running=false;
      cancelAnimationFrame(frame);
    }
  };

  document.querySelectorAll('.edition').forEach((tile,index)=>{
    const canvas=tile.querySelector('.edition-canvas');
    const kind=tile.dataset.edition;
    const ctx=canvas.getContext('2d',{alpha:false});
    renderCoin(ctx,canvas.width,canvas.height,[.10,.42,.67,.84][index],palettes[kind],true);
  });

  document.querySelectorAll('button.buy').forEach(button=>{
    button.addEventListener('click',()=>{
      const old=button.textContent;
      button.textContent='Added to the hoard';
      button.style.background='#77b99d';
      button.style.color='#0b1713';
      setTimeout(()=>{button.textContent=old;button.style.background='';button.style.color=''},1500);
    });
  });
})();
</script>
</body>
</html>
